  "defer.page.html": "<app-demo-page num=\"016\" [snippets]=\"snippets\">\n  <div class=\"layout\">\n    <div class=\"sections\">\n      <section class=\"demo-card\" aria-labelledby=\"d4\">\n        <h3 id=\"d4\">4 · <code>&#64;defer (when showReport())</code></h3>\n        <mat-slide-toggle [checked]=\"showReport()\" (change)=\"showReport.set($event.checked)\">\n          Show report\n        </mat-slide-toggle>\n        @defer (when showReport()) {\n          <app-report-panel />\n        } @placeholder {\n          <p class=\"placeholder\">The report chunk loads once the toggle is on.</p>\n        }\n      </section>\n\n      <section class=\"demo-card\" aria-labelledby=\"d2\">\n        <h3 id=\"d2\">2 · Rich text editor <code>&#64;defer (on interaction)</code></h3>\n        @defer (on interaction) {\n          <app-rich-text-editor />\n        } @placeholder {\n          <button mat-stroked-button type=\"button\">\n            <mat-icon>edit</mat-icon>Click to load the editor\n          </button>\n        } @error {\n          <p role=\"alert\">Could not load the editor.</p>\n        }\n      </section>\n\n      <section class=\"demo-card\" aria-labelledby=\"d3\">\n        <h3 id=\"d3\">3 · Help <code>&#64;defer (on hover; prefetch on idle)</code></h3>\n        @defer (on hover; prefetch on idle) {\n          <app-help-content />\n        } @placeholder {\n          <div class=\"placeholder hover\" tabindex=\"0\">Hover (or focus) me for help</div>\n        }\n      </section>\n\n      <p class=\"spacer demo-hint\" aria-hidden=\"true\">\n        ↓ scroll down – the chart loads when it enters the viewport ↓\n      </p>\n\n      <section class=\"demo-card\" aria-labelledby=\"d1\">\n        <h3 id=\"d1\">1 · Heavy chart <code>&#64;defer (on viewport)</code></h3>\n        @defer (on viewport) {\n          <app-heavy-chart />\n        } @placeholder (minimum 500ms) {\n          <div class=\"placeholder chart\">Chart placeholder (≥ 500 ms)</div>\n        } @loading (after 100ms; minimum 1s) {\n          <div class=\"placeholder chart\">\n            <mat-progress-spinner mode=\"indeterminate\" diameter=\"32\" aria-label=\"Loading chart\" />\n          </div>\n        } @error {\n          <p role=\"alert\">Could not load the chart.</p>\n        }\n      </section>\n    </div>\n\n    <aside class=\"demo-stack side\">\n      <app-event-log title=\"Chunk log\" [entries]=\"log.entries()\" (cleared)=\"log.clear()\" />\n      <div class=\"demo-card hint\">\n        <h3>Check the Network tab</h3>\n        <p class=\"demo-hint\">\n          Open DevTools → Network → JS and trigger each block. Every component arrives as its own\n          lazy chunk (see README → “Deferred chunks”).\n        </p>\n      </div>\n    </aside>\n  </div>\n</app-demo-page>\n",
