  "defer.page.ts": "import { Component, inject, signal } from '@angular/core';\nimport { MatButtonModule } from '@angular/material/button';\nimport { MatIconModule } from '@angular/material/icon';\nimport { MatProgressSpinnerModule } from '@angular/material/progress-spinner';\nimport { MatSlideToggleModule } from '@angular/material/slide-toggle';\nimport { DemoPage } from '../../shared/demo-page/demo-page';\nimport { EventLog } from '../../shared/event-log/event-log';\nimport { DeferLog } from './defer-log';\nimport { SNIPPETS } from './defer.snippets';\nimport { HeavyChart } from './heavy-chart';\nimport { HelpContent } from './help-content';\nimport { ReportPanel } from './report-panel';\nimport { RichTextEditor } from './rich-text-editor';\n\n/**\n * Video 016 – @defer. The four imported components are only used inside @defer blocks,\n * so the compiler moves each of them into its own lazy chunk.\n */\n@Component({\n  selector: 'app-defer-page',\n  imports: [\n    DemoPage,\n    EventLog,\n    HeavyChart,\n    HelpContent,\n    MatButtonModule,\n    MatIconModule,\n    MatProgressSpinnerModule,\n    MatSlideToggleModule,\n    ReportPanel,\n    RichTextEditor,\n  ],\n  providers: [DeferLog],\n  templateUrl: './defer.page.html',\n  styleUrl: './defer.page.scss',\n})\nexport class DeferPage {\n  readonly log = inject(DeferLog);\n  readonly snippets = SNIPPETS;\n  readonly showReport = signal(false);\n}\n",
  "heavy-chart.ts": "import { Component, computed, inject } from '@angular/core';\nimport { DeferLog } from './defer-log';\n\nconst POINTS = 4000;\n\n/** A \"heavy\" SVG chart with thousands of data points – a good candidate for @defer. */\n@Component({\n  selector: 'app-heavy-chart',\n  template: `\n    <svg\n      viewBox=\"0 0 800 200\"\n      role=\"img\"\n      [attr.aria-label]=\"'Line chart with ' + count + ' points'\"\n    >\n      <path [attr.d]=\"area()\" class=\"area\" />\n      <path [attr.d]=\"line()\" class=\"line\" />\n    </svg>\n    <p class=\"demo-hint\">{{ count }} data points, rendered as one SVG path.</p>\n  `,\n  styles: `\n    svg {\n      width: 100%;\n      height: 200px;\n      display: block;\n    }\n    .line {\n      fill: none;\n      stroke: var(--mat-sys-primary);\n      stroke-width: 1.5;\n    }\n    .area {\n      fill: var(--mat-sys-primary-container);\n      opacity: 0.6;\n    }\n  `,\n})\nexport class HeavyChart {\n  readonly count = POINTS;\n  readonly #data = Array.from(\n    { length: POINTS },\n    (_, i) => 100 + 60 * Math.sin(i / 90) + 25 * Math.sin(i / 13) + 10 * Math.cos(i / 3),\n  );\n  readonly line = computed(() =>\n    this.#data\n      .map(\n        (y, i) =>\n          `${i ? 'L' : 'M'}${((i / (POINTS - 1)) * 800).toFixed(1)},${(200 - y).toFixed(1)}`,\n      )\n      .join(''),\n  );\n  readonly area = computed(() => `${this.line()}L800,200L0,200Z`);\n\n  constructor() {\n    inject(DeferLog).loaded('HeavyChart (on viewport)');\n  }\n}\n",
  "help-content.ts": "import { Component, inject } from '@angular/core';\nimport { DeferLog } from './defer-log';\n\n@Component({\n  selector: 'app-help-content',\n  template: `\n    <dl>\n      <dt>When is the chunk fetched?</dt>\n      <dd>Prefetched while the browser is idle, rendered on hover – it appears instantly.</dd>\n      <dt>What does &#64;placeholder do?</dt>\n      <dd>It is shown until the trigger fires and is part of the main chunk.</dd>\n      <dt>And &#64;loading?</dt>\n      <dd>Shown while the chunk downloads; \"after\" and \"minimum\" avoid flicker.</dd>\n    </dl>\n  `,\n  styles: `\n    dt {\n      font: var(--mat-sys-title-small);\n    }\n    dd {\n      margin: 0 0 8px;\n    }\n  `,\n})\nexport class HelpContent {\n  constructor() {\n    inject(DeferLog).loaded('HelpContent (on hover, prefetch on idle)');\n  }\n}\n",
  "report-panel.ts": "import { CurrencyPipe } from '@angular/common';\nimport { Component, inject } from '@angular/core';\nimport { DeferLog } from './defer-log';\n\n@Component({\n  selector: 'app-report-panel',\n  imports: [CurrencyPipe],\n  template: `\n    <table>\n      <caption>\n        Quarterly report\n      </caption>\n      <thead>\n        <tr>\n          <th scope=\"col\">Quarter</th>\n          <th scope=\"col\">Revenue</th>\n        </tr>\n      </thead>\n      <tbody>\n        @for (row of rows; track row.q) {\n          <tr>\n            <td>{{ row.q }}</td>\n            <td>{{ row.revenue | currency: 'EUR' : 'symbol' : '1.0-0' }}</td>\n          </tr>\n        }\n      </tbody>\n    </table>\n  `,\n  styles: `\n    table {\n      border-collapse: collapse;\n      width: 100%;\n    }\n    caption {\n      text-align: start;\n      font: var(--mat-sys-title-small);\n    }\n    td,\n    th {\n      padding: 4px 8px;\n      border-bottom: 1px solid var(--mat-sys-outline-variant);\n      text-align: start;\n    }\n  `,\n})\nexport class ReportPanel {\n  readonly rows = [\n    { q: 'Q1', revenue: 120000 },\n    { q: 'Q2', revenue: 135500 },\n    { q: 'Q3', revenue: 151200 },\n    { q: 'Q4', revenue: 172900 },\n  ];\n\n  constructor() {\n    inject(DeferLog).loaded('ReportPanel (when showReport())');\n  }\n}\n",
